// archivo: purchasescontroller.cs
// función: controla las compras y el ingreso de productos al inventario.

using Microsoft.AspNetCore.Mvc;using Microsoft.AspNetCore.Authorization;using AbarrotesInventory.Application.Interfaces;using AbarrotesInventory.Domain.Entities;using AbarrotesInventory.Infrastructure.Data;using Microsoft.EntityFrameworkCore;
// espacio de nombres que organiza las clases del proyecto.
namespace AbarrotesInventory.Web.Controllers;[Authorize] public class PurchasesController(IInventoryService s,AppDbContext db):Controller { public async Task<IActionResult> Index()=>View(await db.Purchases.Include(x=>x.Supplier).OrderByDescending(x=>x.Date).ToListAsync()); [HttpGet] public async Task<IActionResult> Create(){ViewBag.Products=await s.GetProductsAsync();ViewBag.Suppliers=await s.GetSuppliersAsync();return View();}[HttpPost] public async Task<IActionResult> Create(int supplierId,int productId,int quantity,decimal unitCost){try{var u=await db.Users.FirstAsync(x=>x.Username==User.Identity!.Name);var p=new Purchase{Number="C-"+DateTime.Now.ToString("yyyyMMddHHmmssfff"),SupplierId=supplierId,UserId=u.Id};p.Details.Add(new PurchaseDetail{ProductId=productId,Quantity=quantity,UnitCost=unitCost});await s.RegisterPurchaseAsync(p);return RedirectToAction(nameof(Index));}catch(Exception ex){TempData["Error"]=ex.Message;return RedirectToAction(nameof(Create));}}}
